 Label Label(string text,float size,FontStyle style,Color color){return new Label{Text=text,Font=new Font("Segoe UI",size,style),ForeColor=color,BackColor=Color.Transparent,AutoEllipsis=true};}
 void UpdateStatus(){string value=status.Text;bool connected=value=="Connected";bool idle=value=="Disconnected";orb.Active=connected;orb.Tint=connected?Palette.Accent:idle?Palette.Muted:Color.FromArgb(255,190,100);orb.Invalidate();statusTitle.Text=connected?"Connected":idle?"Disconnected":value=="AUTH"?"Signing in…":value=="CONNECTING"||value=="Connecting"?"Connecting…":value=="WAIT"?"Waiting for server…":value=="ASSIGN_IP"||value=="ADD_ROUTES"||value=="GET_CONFIG"?"Setting up connection…":value=="RECONNECTING"?"Reconnecting…":value.StartsWith("Tunnel active")?"Waiting for handshake":value=="Disconnecting"?"Disconnecting…":value;statusTitle.ForeColor=connected?Palette.Accent:Palette.Text;guidance.Text=connected?"Your VPN tunnel is active.":idle?"Connect when you're ready.":"Connection details appear in the activity panel.";}
 Profile Selected {get{return list.SelectedItem as Profile;}}
 void UI(Action action){if(IsDisposed||Disposing)return;if(InvokeRequired){try{BeginInvoke(action);}catch(InvalidOperationException){}}else action();}
 void Log(string text){UI(()=>{if(logs.TextLength>15000)logs.Clear();logs.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);});}
 void ShowProfile(){var p=Selected;detail.Text=p==null?"No connection selected":p.Name;protocol.Text=p==null?"READY WHEN YOU ARE":p.Kind.ToUpperInvariant();engineNote.Text=p==null?"Import a configuration to add your first connection.":VpnSession.Find(p.Kind)==null?"VPN engine is missing — install "+p.Kind+" to connect.":p.Kind+" engine available";if(session==null)guidance.Text=p==null?"Import a profile or choose an existing Sophos connection.":"Connect when you're ready.";Buttons();}
 void RefreshList(){var selected=Selected;string query=search==null?"":search.Text.Trim();var visible=profiles.Where(p=>query.Length==0||(p.Name+" "+p.Kind).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).ToList();list.DataSource=null;list.DataSource=visible;list.DisplayMember="Name";if(selected!=null&&visible.Contains(selected))list.SelectedItem=selected;profileCount.Text="CONNECTIONS  /  "+profiles.Count;ShowProfile();} void Save(){File.WriteAllText(Path.Combine(home,"profiles.json"),new JavaScriptSerializer().Serialize(profiles));RefreshList();}
 void Import(object s,EventArgs e){if(session!=null)return;using(var d=new OpenFileDialog{Filter="VPN configurations|*.conf;*.ovpn;*.scx;*.tgb;*.pro",Multiselect=true}){if(d.ShowDialog()!=DialogResult.OK)return;foreach(var path in d.FileNames){string ext=Path.GetExtension(path).ToLowerInvariant();string kind=ext==".conf"?"WireGuard":ext==".ovpn"?"OpenVPN":"Sophos Connect";if(!profiles.Any(p=>p.Path==path))profiles.Add(new Profile{Name=Path.GetFileNameWithoutExtension(path),Kind=kind,Path=path});}Save();}}
 void Remove(object s,EventArgs e){if(session!=null||Selected==null)return;if(MessageBox.Show("Remove this profile from the list? Original configurations and Sophos profiles will be kept.","Remove profile",MessageBoxButtons.YesNo)==DialogResult.Yes){profiles.Remove(Selected);Save();}}
 async void LoadSophos(object s,EventArgs e){if(session!=null||busy)return;string exe=VpnSession.Find("Sophos Connect");if(exe==null){MessageBox.Show("Install the Sophos Connect engine first.");return;}try{string text=await Task.Run(()=>VpnSession.Run(exe,"list"));foreach(string raw in text.Split('\n')){if(!raw.StartsWith("  ")||raw.StartsWith("    "))continue;string name=raw.Trim();if(name.Length==0||profiles.Any(p=>p.EngineName==name))continue;profiles.Add(new Profile{Name=name,Kind="Sophos Connect",EngineName=name,Path="sophos:"+name});}Save();Log("Existing Sophos connections loaded.");}catch(Exception ex){MessageBox.Show(ex.Message);}}
 string[] Ask(string title,bool username){if(InvokeRequired)return (string[])Invoke(new Func<string,bool,string[]>(Ask),title,username);if(!Visible)RestoreWindow();using(var f=new Form{Text="VPN sign in",Size=new Size(510,300),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Palette.Surface,ForeColor=Palette.Text,Font=new Font("Segoe UI",10)}){var label=new Label{Text=title,Location=new Point(20,15),Size=new Size(455,55)};var user=new TextBox{Location=new Point(150,85),Width=300,Enabled=username};var pass=new TextBox{Location=new Point(150,135),Width=300,UseSystemPasswordChar=true};f.Controls.Add(label);f.Controls.Add(new Label{Text="Username",Location=new Point(20,88),AutoSize=true});f.Controls.Add(user);f.Controls.Add(new Label{Text="Password / OTP",Location=new Point(20,138),AutoSize=true});f.Controls.Add(pass);var ok=new VpnButton{Primary=true,Text="Continue",DialogResult=DialogResult.OK,Location=new Point(230,195),Size=new Size(105,35)};var cancel=new VpnButton{Text="Cancel",DialogResult=DialogResult.Cancel,Location=new Point(345,195),Size=new Size(105,35)};f.Controls.Add(ok);f.Controls.Add(cancel);f.AcceptButton=ok;f.CancelButton=cancel;return f.ShowDialog(this)==DialogResult.OK?new[]{user.Text,pass.Text}:null;}}
 void Buttons(){if(connect==null)return;connect.Enabled=!busy&&session==null&&Selected!=null;disconnect.Enabled=!busy&&session!=null;list.Enabled=!busy&&session==null;search.Enabled=list.Enabled;importButton.Enabled=list.Enabled;sophosButton.Enabled=list.Enabled;removeButton.Enabled=list.Enabled&&Selected!=null;connect.Text=busy&&session!=null?"Working…":"Connect";((VpnButton)connect).Primary=session==null;((VpnButton)disconnect).Primary=session!=null;connect.Invalidate();disconnect.Invalidate();RefreshDesktop();}
 async void Connect(object sender,EventArgs e){
  if(busy||session!=null||Selected==null)return;busy=true;var p=Selected;session=new VpnSession();session.Credentials=Ask;session.Changed=text=>{UI(()=>{status.Text=session==null?"Disconnected":session.State;RefreshDesktop();});Log(text);};Buttons();
  Exception failure=null;try{Log("Starting "+p.Kind+" connection.");await session.Connect(p,home);}catch(Exception ex){failure=ex;}
  if(failure!=null){Log(failure.Message);MessageBox.Show(failure.Message,"Connection could not start");try{await session.Disconnect();session=null;}catch(Exception cleanup){Log("Cleanup requires attention: "+cleanup.Message);}status.Text=session==null?"Disconnected":"Disconnect required";}
  busy=false;Buttons();
 } async Task<bool> Stop(){if(session==null)return true;busy=true;Buttons();try{await session.Disconnect();session=null;status.Text="Disconnected";return true;}catch(Exception ex){Log(ex.Message);MessageBox.Show(ex.Message,"Disconnect requires attention");return false;}finally{busy=false;Buttons();}}
 async void Disconnect(object sender,EventArgs e){if(busy)return;await Stop();}
 async void Poll(object sender,EventArgs e){if(polling||busy||session==null)return;polling=true;var current=session;try{string value=await current.Status();if(current==session){status.Text=value;if(value!=current.State){current.ObserveState(value);}if(value=="Connected"||value.StartsWith("Tunnel active")){await current.RefreshDetails();}if(current==session)RefreshDesktop();}}catch(Exception ex){Log("Status check: "+ex.Message);}finally{polling=false;}}
 async void OnClosing(object sender,FormClosingEventArgs e){if(closing)return;if(busy){e.Cancel=true;return;}if(session==null)return;e.Cancel=true;if(MessageBox.Show("Disconnect the active session and close MultiVPNConnect?","Close",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;if(await Stop()){closing=true;Close();}}
 async void Update(object s,EventArgs e){if(session!=null){MessageBox.Show("Disconnect before updating.");return;}try{ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;using(var client=new WebClient()){client.Headers["User-Agent"]="MultiVPNConnect/"+Version;var json=await client.DownloadStringTaskAsync("https://api.github.com/repos/CS-Colin/MultiVPNConnect/releases/latest");var release=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);var tag=((string)release["tag_name"]).TrimStart('v');System.Version latest,current;if(!System.Version.TryParse(tag,out latest)||!System.Version.TryParse(Version,out current))throw new Exception("Release version is invalid.");if(latest<=current){MessageBox.Show("You have the latest version.");return;}var assets=(object[])release["assets"];string setup=null,checksum=null;foreach(Dictionary<string,object> a in assets){string name=(string)a["name"];if(name=="MultiVPNConnect-Setup.exe")setup=(string)a["browser_download_url"];if(name=="SHA256SUMS.txt")checksum=(string)a["browser_download_url"];}if(setup==null||checksum==null)throw new Exception("This release has no compatible installer and checksum.");if(!setup.StartsWith("https://github.com/CS-Colin/MultiVPNConnect/releases/download/",StringComparison.Ordinal)||!checksum.StartsWith("https://github.com/CS-Colin/MultiVPNConnect/releases/download/",StringComparison.Ordinal))throw new Exception("Unexpected download source.");if(MessageBox.Show("Download and install version "+tag+" from CS-Colin/MultiVPNConnect? The app will close after the installer opens.","Update available",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;string folder=Path.Combine(Path.GetTempPath(),"MultiVPNConnect-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string installer=Path.Combine(folder,"MultiVPNConnect-Setup.exe");await client.DownloadFileTaskAsync(setup,installer);string sums=await client.DownloadStringTaskAsync(checksum);string expected=sums.Split('\n').Select(line=>line.Trim()).Where(line=>line.EndsWith("MultiVPNConnect-Setup.exe",StringComparison.Ordinal)).Select(line=>line.Split(new[]{' ','\t'},StringSplitOptions.RemoveEmptyEntries)[0]).Single();string actual;using(var sha=SHA256.Create())using(var stream=File.OpenRead(installer))actual=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");if(!actual.Equals(expected,StringComparison.OrdinalIgnoreCase))throw new Exception("Installer checksum verification failed.");Process.Start(new ProcessStartInfo(installer){UseShellExecute=true});Application.Exit();}}catch(WebException){MessageBox.Show("No update could be retrieved. Check your internet connection and whether a GitHub Release has been published.");}catch(Exception ex){MessageBox.Show("Update stopped: "+ex.Message);}}

 [STAThread] static void Main(){bool created;using(var mutex=new Mutex(true,"Local\\MultiVPNConnect.Desktop",out created)){
  if(!created){try{using(var signal=EventWaitHandle.OpenExisting("Local\\MultiVPNConnect.Show"))signal.Set();}catch(WaitHandleCannotBeOpenedException){MessageBox.Show("MultiVPNConnect is already running. Open it from the system tray.");}return;}
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  using(var signal=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\MultiVPNConnect.Show"))using(var form=new MainWindow()){
   IntPtr windowHandle=form.Handle;
   var registration=ThreadPool.RegisterWaitForSingleObject(signal,(state,timedOut)=>form.UI(form.RestoreWindow),null,Timeout.Infinite,false);
   try{Application.Run(form);}finally{registration.Unregister(null);}
  }
 }}
